action.code:
# Check all transactions to see what dates are available
for t in transactions:
    print(f"Date: {t['created_at']}, Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}, Amount: {t['amount']}, Description: {t['description']}")

# Let me check all transactions to see what dates we have
for t in transactions:
    print(f"Date: {t['created_at']}, Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}, Amount: {t['amount']}, Description: {t['description']}")

# Let me search for transactions with "Azure" in the description
all_azure_transactions = [t for t in transactions if 'Azure' in t.get('description', '')]
print("Transactions with 'Azure':")
for t in all_azure_transactions:
    print(t)

# Let me also check if I need to look at transactions where Ashlee is the sender (paying back the manager)
# Get more pages to find yesterday's transactions
for page in range(4, 10):
    trans = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not trans:
        break
    azure_trans = [t for t in trans if 'Azure' in t.get('description', '') or t['created_at'].startswith('2023-05-17')]
    if azure_trans:
        print(f"\nPage {page}:")
        for t in azure_trans:
            print(f"{t['created_at']}: {t['sender']['name']} -> {t['receiver']['name']}: ${t['amount']} - {t['description']}")

