    song_detail = apis.spotify.show_song(song_id=song['id'], access_token=token)
    print(f"Song: {song_detail['title']}, Genre: {song_detail.get('genre', 'N/A')}")
    if song_detail.get('genre', '').lower() == 'edm':
        edm_songs.append({
            'title': song_detail['title'],
            'play_count': song_detail.get('play_count', 0)
        })

# Now let's get details for each song in all playlists
all_playlist_songs = []
for playlist in playlists:
    for song_id in playlist['song_ids']:
        song = apis.spotify.show_song(song_id=song_id, access_token=token)
        all_playlist_songs.append(song)

print(f"Total songs in playlists: {len(all_playlist_songs)}")
print("First few playlist songs:")
for song in all_playlist_songs[:3]:
