# Let's get all liked songs with their details
all_edm_songs = []

# Get liked songs details
liked_songs = apis.spotify.show_liked_songs(access_token=token)
for song in liked_songs:
    song_detail = apis.spotify.show_song(song_id=song['song_id'], access_token=token)
    all_edm_songs.append(song_detail)

# Get songs from liked albums
liked_albums = apis.spotify.show_liked_albums(access_token=token)
for album in liked_albums:
    album_detail = apis.spotify.show_album(album_id=album['album_id'], access_token=token)
    for song_id in album_detail.get('song_ids', []):
        song_detail = apis.spotify.show_song(song_id=song_id, access_token=token)
        all_edm_songs.append(song_detail)

# Get songs from playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        song_detail = apis.spotify.show_song(song_id=song_id, access_token=token)
        all_edm_songs.append(song_detail)

print(f"Total songs collected: {len(all_edm_songs)}")
print("\nSongs by genre:")
genres = {}
for song in all_edm_songs:
    genre = song.get('genre', 'Unknown')
    if genre not in genres:
        genres[genre] = []
    genres[genre].append(song)

for genre in sorted(genres.keys()):
    print(f"  {genre}: {len(genres[genre])} songs")

